// PROTOTYPE - NOT FOR PRODUCTION
// Question: Do the farm half and the outing half still feed each other when the world is a boss-gated chain of single-biome maps with a far second village?
// Date: 2026-10-29
//
// Same setup as round 1 and CombatFeel: new empty scene, one empty
// GameObject, add this component, press Play. Round 2: this only creates the
// game, the player and the camera; maps are generated by DayLoopGame on
// demand (DayLoopMapGen.cs) from the world table in DayLoopWorld.cs.

using UnityEngine;

namespace DayLoopProto
{
    public class DayLoopBootstrap : MonoBehaviour
    {
        void Awake()
        {
            var game = new GameObject("DayLoopGame").AddComponent<DayLoopGame>();
            game.Player = BuildPlayer();
            game.Cam = BuildCamera(game.Player.transform);
            game.Begin();
        }

        DayLoopPlayer BuildPlayer()
        {
            var go = new GameObject("Player");
            go.transform.localScale = new Vector3(0.9f, 1.3f, 1f);
            go.AddComponent<SpriteRenderer>().sortingOrder = 4;
            var rb = go.AddComponent<Rigidbody2D>();
            rb.freezeRotation = true;
            rb.collisionDetectionMode = CollisionDetectionMode2D.Continuous;
            rb.interpolation = RigidbodyInterpolation2D.Interpolate;
            go.AddComponent<BoxCollider2D>().size = Vector2.one;
            return go.AddComponent<DayLoopPlayer>();
        }

        CameraFollow BuildCamera(Transform target)
        {
            var cam = Camera.main;
            if (cam == null)
            {
                var camGo = new GameObject("DayLoopCamera");
                cam = camGo.AddComponent<Camera>();
                camGo.tag = "MainCamera";
            }
            cam.orthographic = true;
            cam.orthographicSize = 6.5f;
            cam.backgroundColor = new Color(0.05f, 0.05f, 0.07f);
            var follow = cam.gameObject.AddComponent<CameraFollow>();
            follow.target = target;
            return follow;
        }
    }
}
